#include "(CurrentProject)/js/personaliza/personaWizard.js"

// -------------------------------------
// Cargar los objetos del proyecto
// -------------------------------------

// Atrapar el formulario donde están los controles
var formulario = theRoot.dataView();

// Leer el proyecto seleccionado
var controlProyecto = formulario.control("PRO_GEN_FIC_PRY");
if (controlProyecto)
{
	var proyectoInfo = theApp.projectInfo(controlProyecto.itemData(controlProyecto.currentIndex));
};

// Cargar objetos en el combobox
var objetosInfo = getObjetosProyectoTipoInfo(proyectoInfo, VObjectInfo.TypeProcess);
var controlObjeto = formulario.control("PRO_GEN_FIC_OBJ_ID");
if (controlObjeto)
{
	// Se limpia el contenido antes de añadir el nuevo
	controlObjeto.clear();

	// Se añaden los formularios del proyecto seleccionado que sean de origen ficha de remesa de cobro o pago
	for(numObjeto in objetosInfo)
	{
		if ((objetosInfo[numObjeto].isPrivate() == false) && (objetosInfo[numObjeto].inputType() == VObjectInfo.IORecord) && (objetosInfo[numObjeto].inputTable().id() == "REM_COB_C"))
		{
			controlObjeto.addItem(objetosInfo[numObjeto].id() + "  (" + objetosInfo[numObjeto].name() + ")", objetosInfo[numObjeto].id());
		};

		if ((objetosInfo[numObjeto].isPrivate() == false) && (objetosInfo[numObjeto].inputType() == VObjectInfo.IORecord) && (objetosInfo[numObjeto].inputTable().id() == "REM_PAG_C"))
		{
			controlObjeto.addItem(objetosInfo[numObjeto].id() + "  (" + objetosInfo[numObjeto].name() + ")", objetosInfo[numObjeto].id());
		};
	};

	controlObjeto.setCurrentIndex(controlObjeto.findData(theRegisterIn.fieldToString("PRO_GEN_FIC_OBJ_ID")));
};

#include "(CurrentProject)/js/personaliza/personaWizard.js"

// ------------------------------------
// Cargar proyectos en combobox
// ------------------------------------

// Atrapar el formulario donde están los controles
var formulario = theRoot.dataView();

// Preparar los arrays
var proyectosInfo = [];
var proyectosAlias = [];
var proyectosId = [];
getProyectosHeredadosInfo(theApp.mainProjectInfo(), proyectosInfo, proyectosAlias, proyectosId);

// Se preparan el combobox para cargar los proyectos
var controlProyecto = formulario.control("PRO_GEN_FIC_PRY");

// Limpiar el contenido de los controles
controlProyecto.clear();

// Cargar los proyectos en los controles
for(numProyecto in proyectosInfo)
{
	// Se cargan todos los tipos de proyectos
	controlProyecto.addItem(proyectosInfo[numProyecto].name(), proyectosInfo[numProyecto].alias());
};

controlProyecto.setCurrentIndex(controlProyecto.findData(theRegisterIn.fieldToString("PRO_GEN_FIC_PRY")));

