#include "(CurrentProject)/js/personaliza/personaWizard.js"

// ------------------------------------
// Cargar proyectos en combobox
// ------------------------------------

// Atrapar el formulario donde están los controles
var formulario = theRoot.dataView();

// Preparar los arrays
var proyectosInfo = [];
var proyectosAlias = [];
var proyectosId = [];
getProyectosHeredadosInfo(theApp.mainProjectInfo(), proyectosInfo, proyectosAlias, proyectosId);

// Se preparan el combobox para cargar los proyectos
var controlProyecto = formulario.control("PRO_PRT_PRY");

// Limpiar el contenido de los controles
controlProyecto.clear();

// Cargar los proyectos en los controles
for(numProyecto in proyectosInfo)
{
	// Se cargan sólo los proyectos de aplicación
	if (proyectosInfo[numProyecto].type() == VProjectInfo.TypeApp)
	{
		controlProyecto.addItem(proyectosInfo[numProyecto].name(), proyectosInfo[numProyecto].alias());
	};
};

controlProyecto.setCurrentIndex(controlProyecto.findData(theRegisterIn.fieldToString("PRO_PRT_PRY")));

// -----------------------------------------------
// Pasar el valor de los combobox a campos
// -----------------------------------------------

// Atrapar el formulario donde están los controles
var formulario = theRoot.dataView();

// Proyecto del proceso de generación de fichero
var control = formulario.control("PRO_GEN_FIC_PRY");
if (control.itemData(control.currentIndex))
{
	theRegisterIn.setField("PRO_GEN_FIC_PRY", control.itemData(control.currentIndex));
};

// Objeto del proceso de generación de fichero
var control = formulario.control("PRO_GEN_FIC_OBJ_ID");
if (control.itemData(control.currentIndex))
{
	theRegisterIn.setField("PRO_GEN_FIC_OBJ_ID", control.itemData(control.currentIndex));
};

// Proyecto del proceso de emisión
var control = formulario.control("PRO_PRT_PRY");
if (control.itemData(control.currentIndex))
{
	theRegisterIn.setField("PRO_PRT_PRY", control.itemData(control.currentIndex));
};

// Objeto del proceso de emisión
var control = formulario.control("PRO_PRT_OBJ_ID");
if (control.itemData(control.currentIndex))
{
	theRegisterIn.setField("PRO_PRT_OBJ_ID", control.itemData(control.currentIndex));
};
